def build(ctx,feature):
 base=float(feature.get('base_m',0));h=27.5
 brick=ctx.material('Albert Court estimated red brick',(.39,.16,.11),.86)
 terra=ctx.material('Albert Court estimated terracotta',(.45,.21,.14),.82)
 stone=ctx.material('Albert Court pale sash and dressings',(.77,.75,.67),.62)
 slate=ctx.material('Albert Court dark pitched roof',(.15,.17,.18),.86)
 glass=ctx.material('Albert Court estimated grey glass',(.14,.20,.22),.19,0,.28)
 metal=ctx.material('Albert Court dark iron',(.028,.033,.033),.44,.65)
 timber=ctx.material('Albert Court estimated entrance timber',(.10,.055,.035),.68)
 wall=ctx.mesh('full mapped bay outline and nine open lightwells');roof=ctx.mesh('complete mansard roof retaining mapped holes');win=ctx.mesh('recessed estimated sash rhythm');trim=ctx.mesh('simple cornices and brick bands');entry=ctx.mesh('estimated Prince Consort Road entrance')
 for tr in ROOF:roof.face([(x,y,base+z) for x,y,z in tr],slate)
 for a,b in STEPS:roof.face([(a[0],a[1],base+31.4),(b[0],b[1],base+31.4),(b[0],b[1],base+33.5),(a[0],a[1],base+33.5)],slate)
 entrances=[]
 for part in feature['geometry']:
  for ri,ring in enumerate([part['outer']]+part.get('holes',[])):
   h=27.5 if ri==0 else 31.4
   for ei,(a,b) in enumerate(zip(ring,ring[1:]+ring[:1])):
    L=math.dist(a,b);tx,ty=(b[0]-a[0])/L,(b[1]-a[1])/L;nx,ny=ty,-tx
    def p(s,d,z):return(a[0]+tx*s+nx*d,a[1]+ty*s+ny*d,base+z)
    angle=math.atan2(ty,tx)
    def bx(m,s,d,z,w,dep,hh,mat):m.box(*p(s,d,z),w,dep,hh,mat,angle)
    apertures=[]
    if L>1.15:
     count=max(1,int(L/3.1));pitch=L/count;ww=min(1.34,pitch*.57)
     for k in range(count):
      c=(k+.5)*pitch
      for row in range(7):
       lo=1.0+row*3.8;hi=lo+(2.35 if row<5 else 2.05);door=ri==0 and ei==12 and k==count//2 and row==0
       w=1.72 if door else ww;low=.08 if door else lo;high=3.12 if door else hi
       apertures.append((c-w/2,c+w/2,low,high,door))
    xs=sorted(set([0,L]+[xx for op in apertures for xx in op[:2]]))
    for aa,bb in zip(xs,xs[1:]):
     hits=sorted([op for op in apertures if op[0]<(aa+bb)/2<op[1]],key=lambda x:x[2]);z=0
     for op in hits+[(0,0,h,h,False)]:
      if op[2]>z:wall.face([p(aa,0,z),p(bb,0,z),p(bb,0,op[2]),p(aa,0,op[2])],brick)
      z=op[3]
    for aa,bb,lo,hi,door in apertures:
     c=(aa+bb)/2;w=bb-aa;d=.43 if door else .20
     bx(entry if door else win,c,-d,(lo+hi)/2,w,.06,hi-lo,timber if door else glass)
     for ss in [aa,bb]:wall.face([p(ss,0,lo),p(ss,-d,lo),p(ss,-d,hi),p(ss,0,hi)],terra)
     for zz in [lo,hi]:wall.face([p(aa,0,zz),p(bb,0,zz),p(bb,-d,zz),p(aa,-d,zz)],terra)
     for ss in [aa-.04,bb+.04]:bx(win,ss,.005,(lo+hi)/2,.08,.14,hi-lo+.12,stone)
     bx(win,c,.04,hi+.055,w+.18,.20,.11,stone)
